    public static Dictionary<string,bool> Check(string output){var c=new Dictionary<string,bool>();var q=new QuietHours();DateTime time=new(2026,10,17);c["quiet_cross_midnight_boundaries"]=q.Contains(time.AddHours(23))&&q.Contains(time.AddHours(7).AddMinutes(59))&&!q.Contains(time.AddHours(8))&&!q.Contains(time.AddHours(22).AddMinutes(59));q=new(true,9*60,17*60);c["quiet_daytime_and_disabled"]=q.Contains(time.AddHours(9))&&!q.Contains(time.AddHours(17))&&!(q with{Enabled=false}).Contains(time.AddHours(12));string root=Path.Combine(output,"test36-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string path=Path.Combine(root,"leo-todos.json");var store=new TodoStore(path);var today=DateOnly.FromDateTime(DateTime.Today);var task=store.AddRepeating("每周踢球",today,"weekly",DateTimeOffset.Now.AddMinutes(-1));var second=store.Items.First(t=>t.Id!=task.Id);store.Delete(second.Id);store.BackupNow();var snapshot=store.Backups().First(f=>f.EndsWith("-manual.json"));var raw=File.ReadAllText(snapshot);c["backup_keeps_recurrence_rules_and_tombstones"]=raw.Contains("weekly")&&raw.Contains("\"Deleted\":true");store.Rename(task.Id,"改名后的踢球");string latest=Path.Combine(store.BackupDirectory!,"latest.json");c["latest_backup_follows_every_change"]=JsonSerializer.Deserialize<List<DailyTask>>(File.ReadAllText(latest))!.Any(t=>t.Title=="改名后的踢球");store.RestoreBackup(snapshot);c["restore_keeps_rules_and_deleted_occurrences"]=store.Items.First(t=>t.Id==task.Id).Title=="每周踢球"&&store.Items.All(t=>t.Id!=second.Id)&&store.RuleFor(task.SeriesId)?.Frequency=="weekly";c["restore_retains_pre_restore_copy"]=store.Backups().Any(f=>f.EndsWith("-before-restore.json")&&JsonSerializer.Deserialize<List<DailyTask>>(File.ReadAllText(f))!.Any(t=>t.Title=="改名后的踢球"));string invalid=Path.Combine(store.BackupDirectory!,"invalid.json");File.WriteAllText(invalid,"{broken");string before=File.ReadAllText(path);bool rejected=false;try{store.RestoreBackup(invalid);}catch{rejected=true;}c["invalid_backup_cannot_overwrite_current_data"]=rejected&&File.ReadAllText(path)==before;var due=store.Due(DateTimeOffset.Now);c["deferred_reminders_remain_pending_after_restart"]=due.Any(t=>t.Id==task.Id)&&new TodoStore(path).Due(DateTimeOffset.Now).Any(t=>t.Id==task.Id);c["daily_backup_created_on_startup_or_write"]=store.Backups().Any(f=>f.EndsWith("-daily.json"));
        var song=new MusicSong("97773","0039MnYb0qxYhV","晴天","周杰伦","叶惠美");string libraryPath=Path.Combine(root,"playlists.json");var library=new MusicLibrary(libraryPath);var one=library.Create("踢球路上");var two=library.Create("安静一会儿");library.Add(one.Id,song);library.Add(one.Id,song);library.Pin(two.Id);var loaded=new MusicLibrary(libraryPath);c["playlist_pins_and_tracks_survive_restart"]=loaded.Items.Single(p=>p.Id==one.Id).Songs.Count==1&&loaded.Items.Single(p=>p.Id==one.Id).Pinned&&!loaded.Items.Single(p=>p.Id==two.Id).Pinned;library.RemoveSong(one.Id,song.Id);c["remove_track_preserves_playlist"]=new MusicLibrary(libraryPath).Items.Single(p=>p.Id==one.Id).Songs.Count==0;
        using(var silent=new MusicForm(true)){var list=silent.Library.Create("只听一首");silent.Library.Add(list.Id,song);c["playlist_tool_dispatch_does_not_open_intermediate_window"]=silent.PlayPlaylist(list.Id).GetAwaiter().GetResult()&&!silent.Visible;c["unknown_or_empty_playlist_does_not_dispatch"]=!silent.PlayPlaylist("missing").GetAwaiter().GetResult()&&!silent.PlayPlaylist(silent.Library.Create("空歌单").Id).GetAwaiter().GetResult();}
        using(var music=new MusicForm(true)){var a=music.Library.Create("赛前热身");music.Library.Add(a.Id,song);var b=music.Library.Create("路上随手听");music.Library.Add(b.Id,new("639147","000i9BX94fzhzv","You're Not Sorry","Taylor Swift"));music.Home();music.Show();Application.DoEvents();Capture(music,"preview-music-home.png");c["music_home_contains_pinned_playlist_play_buttons"]=All(music).OfType<BarcaButton>().Count(b=>b.Text=="▶ 点首曲")==2;All(music).OfType<BarcaButton>().First(b=>b.Text=="▶ 点首曲").PerformClick();c["playlist_one_click_dispatch_and_local_history"]=All(music).OfType<Label>().Any(l=>l.Text.Contains("已发送到QQ音乐：晴天"));}
        File.Delete(invalid);using(var settings=new PlannerSettings(store)){settings.Show();Application.DoEvents();Capture(settings,"preview-planner-settings.png");}using(var todo=new TodoForm(true,store)){todo.Show();Application.DoEvents();Capture(todo,"preview-planner36.png");}return c;
        void Capture(Form form,string name){using var b=new Bitmap(form.Width,form.Height);form.DrawToBitmap(b,form.ClientRectangle);b.Save(Path.Combine(output,name));}
